cd /work; mkdir -p resources; cd resources
cat > ../Caddyfile <<'E'
{
	admin off
}
:8089 {
	resource {
		dir resources
		dsn postgres://eval_rw:eval_rw@postgres:5432/llmapi_eval
	}
}
E
cat > Author.json <<'E'
{"name":"Author","path":"/authors","table":"author","itemsPerPage":2,
"properties":{"id":{"type":"integer","identifier":true,"readOnly":true},"name":{"type":"string"}}}
E
cat > Book.json <<'E'
{"name":"Book","path":"/books","query":"book.query.ts","command":"book.command.ts","itemsPerPage":2,
"input":{"title":{"type":"string","required":true},"author_id":{"type":"integer","required":true},"published":{"type":"boolean"}},
"properties":{"id":{"type":"integer","identifier":true},"title":{"type":"string"},"author":{"type":"string","filterable":true},"published":{"type":"boolean"}}}
E
cat > book.query.ts <<'E'
export default function query(ctx) {
  return ctx.sql`SELECT b.id, b.title, a.name AS author, b.published FROM book b LEFT JOIN author a ON a.id = b.author_id WHERE b.published`;
}
E
cat > book.command.ts <<'E'
function checkAuthor(authorId, published, ctx) {
  const [a] = ctx.db.query(ctx.sql`SELECT name FROM author WHERE id = ${authorId}`);
  if (!a) ctx.reject({ message: `author ${authorId} does not exist`, pointer: "/author_id" });
  if (published && (a.name === null || a.name === "")) {
    ctx.reject({ message: "a book whose author has no name cannot be published", pointer: "/published" });
  }
}
export function create(input, ctx) {
  const published = input.published === true;
  checkAuthor(input.author_id, published, ctx);
  const [row] = ctx.db.query(ctx.sql`INSERT INTO book (title, author_id, published) VALUES (${input.title}, ${input.author_id}, ${published}) RETURNING id`);
  return row.id;
}
export function update(input, ctx) {
  const [b] = ctx.db.query(ctx.sql`SELECT title, author_id, published FROM book WHERE id = ${ctx.id}`);
  const t = "title" in input ? input.title : b.title;
  const aid = "author_id" in input ? input.author_id : b.author_id;
  const p = "published" in input ? input.published === true : b.published;
  checkAuthor(aid, p, ctx);
  ctx.db.exec(ctx.sql`UPDATE book SET title = ${t}, author_id = ${aid}, published = ${p} WHERE id = ${ctx.id}`);
}
export function remove(input, ctx) {
  ctx.db.exec(ctx.sql`DELETE FROM book WHERE id = ${ctx.id}`);
}
E
cat > Quote.json <<'E'
{"name":"Quote","path":"/quotes","query":"quote.query.ts","readOnly":true,"itemsPerPage":2,
"allow":{"fetch":["127.0.0.1:18090"]},
"properties":{"id":{"type":"integer","identifier":true},"text":{"type":"string"},"author":{"type":"string","filterable":true}}}
E
cat > quote.query.ts <<'E'
export default async function query(ctx) {
  const res = await ctx.fetch("http://127.0.0.1:18090/quotes.json");
  let rows = (await res.json()).map((q) => ({ id: q.id, text: q.quote, author: q.by }));
  rows.sort((a, b) => a.id - b.id);
  if (ctx.operation === "item") return rows.find((r) => r.id === ctx.id) ?? null;
  if (ctx.filters.author !== undefined) rows = rows.filter((r) => r.author === ctx.filters.author);
  const start = (ctx.page - 1) * ctx.itemsPerPage;
  return { items: rows.slice(start, start + ctx.itemsPerPage), totalItems: rows.length };
}
E
cat > Export.json <<'E'
{"name":"AuthorReport","operations":[{"method":"GET","path":"/business/export","format":"csv","query":"export.query.ts"}],
"properties":{"author":{"type":"string"},"published_books":{"type":"integer"}}}
E
cat > export.query.ts <<'E'
export default function query(ctx) {
  return ctx.sql`SELECT a.name AS author, count(b.id) FILTER (WHERE b.published)::int AS published_books FROM author a LEFT JOIN book b ON b.author_id = a.id WHERE a.name IS NOT NULL AND a.name <> '' GROUP BY a.id, a.name ORDER BY a.name, a.id`;
}
E
cd ..; ./caddy resource validate --dir resources --dsn postgres://eval_rw:eval_rw@postgres:5432/llmapi_eval

